custom_css:
/* ----------
来自@咩野(dc@lambkinling);
有使用KAKAA老师二改盒子中的部分代码、以及NAKARI和墨千尾老师在教程帖分享的代码；
二改需标注，禁二传，倒卖👊🏻👊🏻👊🏻；
 ---------- */

/* ----- 自定义变量 ------ */
:root {
  /* 顶栏图标大小 */
  --topBarIconSize: calc(var(--mainFontSize) * 1.3);
  /* 边框圆角 */
  --border-radius-small: 15px;
  /* 颜色 */
  --theme-color-1: #6A5343;
  --theme-color-2: #F6EFDC;
  --theme-color-3: color-mix(in srgb, var(--theme-color-1) 85%, white);
}

/* ----- 字体样式 ------ */
/* 引用文本 */
q {

}

/* 斜体 */
em {
  font-style: italic;
  text-decoration: underline currentColor 0.08em wavy;
  text-underline-offset: 4px;
}

/* 行内代码 */
code, pre {
  margin: 0;
  border-radius: 3px;
  border: 2px double var(--theme-color-2);
  background: 
   linear-gradient(rgba(0, 0, 0, 0.1) 1px, transparent 1px) 0 0 / 12px 12px,
   linear-gradient(90deg, rgba(0, 0, 0, 0.1) 1px, transparent 1px) 0 0 / 12px 12px;
  color: var(--SmartThemeBodyColor);
  background-color: color-mix(in srgb, var(--theme-color-1) 75%, white) !important;
  line-height: 1.7;
}

/* 删除文本 */
del, s {
  color: red;
}

/* ----- 滚动条 ------ */
/* 滚动条 */
::-webkit-scrollbar {
  display: none;
}

/* Firefox 全局滚动条样式 */
html {
  scrollbar-width: auto;
  scrollbar-color: var(--theme-color-1) #f1f1f1;
}

/* 滑动条 */
input[type="range"] {
  background-color: var(--theme-color-1) !important;
  filter: none !important;
  box-shadow: inset 0px -1px 2px rgba(0, 0, 0, 0.3) !important;
}

/* 滑动条滑块 */
input[type="range"]::-webkit-slider-thumb {
  width: 32px;
  height: 32px; 
  background-image: url('https://files.catbox.moe/esvlpn.png');
  background-size: contain;
  background-repeat: no-repeat;
  background-color: transparent !important;
  border: none;
}

/* ----- 聊天区域 ------ */
/* 思维链 - 移除默认样式*/
.mes_reasoning_header {
  position: relative;
  cursor: pointer;
  border: none !important;
  background: none !important;
  color: transparent;
}

/* 默认zz小猫 */
.mes_reasoning_header::before {
  content: "";
  position: absolute;
  top: -10px;
  left: 0;
  width: 11dvh;
  aspect-ratio: 1240 / 824;
  transform: rotate(-4deg);
  background-image: url('https://files.catbox.moe/1r53we.png');
  background-size: contain;
  background-repeat: no-repeat;
}

/* o_-小猫 */
.mes_reasoning_header:hover::before {
  background-image: url('https://files.catbox.moe/z6614z.png');
}

/* 聊天框 */
#sheld {
  top: var(--topBarBlockSize);
  height: calc(100dvh - var(--topBarBlockSize) - 1px);
  min-height: calc(100dvh - var(--topBarBlockSize)); /* ⚠️用视觉小说模式就把一行删掉 */
}

#chat {
  align-items: center;
  max-height: calc(100dvh - var(--topBarBlockSize) - 20px) !important;
  background: transparent;
  border: none;
  padding: 0;
}

@supports(-webkit-touch-callout: none){
  #chat{
    padding-right: 4px;
  }
}

/* 气泡框 */
.mes {
  flex-direction: column;
  align-items: center;
  width: 95%;
  border-radius: 15px;
  background: var(--theme-color-2);
  box-shadow: 
    1px 1px 0 3px var(--theme-color-1),
    -1px 1px 0 3px var(--theme-color-1),
    1px -1px 0 3px var(--theme-color-1),
    -1px -1px 0 3px var(--theme-color-1);
  border: 2px dashed var(--theme-color-1);
  outline: 2px solid var(--theme-color-2);
  margin: 15px auto;
  padding: 20px 0;
}

.mes:hover {
  transform: translateY(-2px);
}

/* 🐈‍⬛ai - 默认小猫贴纸 */
.mes[is_user="false"]:hover::after {
  content: "";
  position: absolute;
  z-index: 1;
  width: 10dvh;
  aspect-ratio: 644 / 1024;
  background-image: url('https://files.catbox.moe/9x6nw6.png');
  background-size: contain;
  background-repeat: no-repeat;
  right: 26px;
  top: -25px;
  transform: translateX(50%);
  pointer-events: none;
}

/* 🐈用户 - 默认小猫贴纸 */
.mes[is_user="true"]:hover::before {
  content: "";
  position: absolute;
  z-index: 1;
  width: 10dvh;
  aspect-ratio: 589 / 754;
  background-image: url('https://files.catbox.moe/o65pvg.png');
  background-size: contain;
  background-repeat: no-repeat;
  left: 20%;
  top: 19px;
  transform: translateX(-50%);
  pointer-events: none;
  filter: brightness(0.99);
}

/* 🐈用户 - 悬停小猫 */
.mes[is_user="true"]::before {
  content: "";
  position: absolute;
  z-index: 1;
  width: 16dvh; /* 大小 */
  aspect-ratio: 1231 / 913;
  background-image: url('https://files.catbox.moe/7rav0j.png');
  background-size: contain;
  background-repeat: no-repeat;
  left: 17%;  /* 左右 */
  top: 23px; /* 上下位置 */
  transform: translateX(-50%) scaleX(-1);
  pointer-events: none;
  filter: brightness(0.99);
  z-index: 1;
}

/* 用户消息悬停时隐藏::after */
.mes[is_user="true"]:hover::after {
  opacity: 0;
}

/* 🐈‍⬛AI - 悬停小猫 */
.mes[is_user="false"]::after {
  content: "";
  position: absolute;
  z-index: 1;
  width: 18dvh; /* 大小 */
  aspect-ratio: 1240 / 824;
  background-image: url('https://files.catbox.moe/n1sffj.png');
  background-size: contain;
  background-repeat: no-repeat;
  right: 19%;  /* 左右 */
  top: 18px; /* 上下位置 */
  transform: translateX(50%);
  pointer-events: none;
}

/* AI消息悬停时隐藏::before */
.mes[is_user="false"]:hover::before {
  opacity: 0;
}

/* 头像区域 */
.mesAvatarWrapper {
  display: flex;
  position: relative;
  gap: 15px 10px;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  width: 100%;
  margin-bottom: 10px;
  pointer-events: none;
}

/* 头像区域下方横线 */
.mesAvatarWrapper::after {
  content: "";
  position: absolute;
  bottom: -2px;
  left: 50%;
  transform: translateX(-50%);
  width: 80%; /* 固定长度 */
  height: 1px;
  background: 
    linear-gradient(to left, 
    rgba(106, 83, 67, 0),
    rgba(0, 0, 0, 0.1), 
    rgba(106, 83, 67, 0));
}

  /* 头像容器 */
.mesAvatarWrapper .avatar {
  display: flex;
  flex-basis: 100%;
  justify-content: center;
  align-items: center;
  -webkit-transform: scale(1.5);
  transform: scale(1.5); /* 头像大小 */
}

/* 🔸猫猫头(可删)
.mesAvatarWrapper .avatar img {
  -webkit-mask-image: url('https://files.catbox.moe/wxywdl.png');
  mask-image: url('https://files.catbox.moe/wxywdl.png');
  -webkit-mask-size: contain;
  mask-size: contain;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
  pointer-events: auto;
}  */

/* 文字区域 */
.mes_block {
  padding: 0 13px;
}

/* 文本样式 */
.mes_text {
  background:
    linear-gradient(90deg, var(--theme-color-2) 20%, transparent 0%) 0 0 / 15px 15px,
    linear-gradient(rgba(0, 0, 0, 0.08) 7%, transparent 0%) 0 0 / 18px 18px;
   padding: 0;
   text-align: justify;
}

/* 最后一条消息 */
.last_mes {
  margin-bottom: 60px !important;
}

.last_mes .mesAvatarWrapper {
  padding-bottom: 0 !important;
}

div[is_user="false"].last_mes {
  padding-bottom: 50px;
}

/* 楼层、计时器、tokens */
.mesIDDisplay:empty,
.mes_timer:empty,
.tokenCounterDisplay:empty {
  display: none;
}

/* 编辑按钮 */
.mes_button,
.mes_edit_buttons {
  filter: none !important;
  box-shadow: none;
  font-size: calc(var(--mainFontSize) * 1.1);
}

/* 更换图标 */
.mes_button.mes_edit.fa-solid.fa-pencil {
  /* 移除 Font Awesome 图标 */
  font-family: inherit !important;

  /* 移除伪元素内容 */
  &::before {
    content: "" !important;
  }
  background-image: url('https://files.catbox.moe/r188ci.png');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  width: 18px; 
  height: 18px;
  display: inline-block;
  text-indent: -9999px;
  overflow: hidden;
}

/* 左右箭头 */
.swipe_right, .swipe_left {
    font-family: unset !important;
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
    width: 32px;
    height: 32px;
    text-indent: -9999px;
}

/* 替换右箭头 */
.swipe_left {
    background-image: url('https://files.catbox.moe/uqn9xo.png');
}

/* 替换左箭头 */
.swipe_right {
  background-image: url('https://files.catbox.moe/uqn9xo.png');
  transform: scaleX(-1);
  margin-right: 20px;
}

/* ----- 顶栏 & 底栏 ----- */
/* 去除底部菜单列表阴影 */
.list-group,
.options-content,
#options {
  box-shadow: none !important;
}

/* 悬浮输入栏 byNAKARI */
#form_sheld {
  position: absolute;
  bottom: 5px;
}

/* --- 顶栏 ---- */
body.no-blur #top-bar,
#top-bar {
  background: var(--theme-color-3) !important;
  background-color: #fff;
  border-radius: 0 0 var(--border-radius-small) var(--border-radius-small);
  border-bottom: 1.5px solid var(--theme-color-1);
  box-shadow: none;
}

/* 顶栏容器 */
#top-settings-holder {
  top: 0;
  box-shadow: none;
  justify-content: center;
  align-items: center;
}

/* 顶栏图标样式 */
.drawer-icon.fa-fw {
  overflow: visible;
  position: relative;
  z-index: 1;
  height: 28px;
  width: 28px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  filter: none !important;
  transition: all 0.4s ease;
  opacity: 1;
}

/* 悬停效果 */
.drawer-icon.fa-fw:hover {
  animation: catShake 0.5s infinite alternate;
}

@keyframes catShake {
  0% { transform: rotate(-5deg); }
  25% { transform: rotate(5deg) scale(1.1); }
  50% { transform: rotate(-3deg); }
  75% { transform: rotate(2deg); }
  100% { transform: rotate(0); }
}

/* 隐藏原有顶栏图标 */
.drawer-icon.fa-fw::before {
  display: none;
}

/* 顶栏图标自定义 */
/* 白色小猫 */
#ai-config-button .drawer-icon,
#advanced-formatting-button .drawer-icon,
#user-settings-button .drawer-icon,
#extensions-settings-button .drawer-icon,
#persona-management-button .drawer-icon { 
  background-image: url('https://files.catbox.moe/28lmyu.png'); 
}

/* 黑色小猫 */
#sys-settings-button .drawer-icon,
#WI-SP-button .drawer-icon,
#logo_block .drawer-icon,
#table_database_settings_drawer .drawer-icon,
#rightNavHolder .drawer-icon{ 
  background-image: url('https://files.catbox.moe/fycjv6.png');
}

/* 🔥无记忆插件版(用记忆插件删掉这段) */
#persona-management-button .drawer-icon { 
  background-image: url('https://files.catbox.moe/fycjv6.png'); 
}
#rightNavHolder .drawer-icon{ 
  background-image: url('https://files.catbox.moe/28lmyu.png');
}

/* --- 底栏 --- */
body.no-blur #send_form, 
#send_form {
  width: 90%;
  background-color: var(--theme-color-1) !important;
  border-radius: 25px;
  outline: 1.5px solid var(--theme-color-1) !important;
  border: none !important;
  box-shadow:
    3px 3px 8px rgba(0, 0, 0, 0.15),
    -4px -4px 8px rgba(255, 255, 255, 0.35),
    inset -20px -12px 24px 7px var(--theme-color-2),
    inset 20px 12px 24px 7px var(--theme-color-2);
  position: relative;
}

/* 猫耳朵 */
#send_form::before,
#send_form::after {
  content: "";
  position: absolute;
  z-index: 1;
  top: -17.5px;
  width: 35px;
  height: auto;
  aspect-ratio: 2 / 1;
  border-radius: 51% 49% 49% 51% / 100% 100% 0% 0%;
  background: 
    radial-gradient(circle at 50% 100%, var(--theme-color-1) 35%, var(--theme-color-2) 60%);
  box-shadow:
    inset 0 0 15px var(--theme-color-2),
    0 -1px 0 1px var(--theme-color-1);
  transition: all 0.3s ease; 
}

#send_form::before {
  left: 20%;
}

#send_form::after {
  right: 20%;
}

/* 底栏图标按钮 */
#options_button,
#extensionsMenuButton,
#send_but,
#quick-reply-rocket-button,
.fa-solid .fa-circle-stop {
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  position: relative;
  -webkit-filter: none !important; 
  filter: none !important;
  transition: all 0.3s ease;
}

/* 底栏图标大小 */
#send_form .fa-solid {
  font-size: calc(var(--mainFontSize) * 1.5);
}

/* 基础样式 */
#options_button,
#send_but {
  transition: all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  transform-origin: center;
}

/* 悬停效果 - 猫爪按压动画 */
#options_button:hover,
#send_but:hover,
.fa-solid .fa-circle-stop
 {
  transform: scale(0.9) translateY(2px);
  filter: drop-shadow(0 2px 4px rgba(255, 105, 180, 0.3));
  animation: pawPress 0.4s ease-out;
}

@keyframes pawPress {
  0% { transform: scale(1); }
  50% { transform: scale(0.85) translateY(3px); }
  100% { transform: scale(0.9) translateY(2px); }
}

/* 基础样式 */
#extensionsMenuButton,
#quick-reply-rocket-button {
  transition: all 0.4s ease;
  opacity: 0.9;
}

/* 悬停效果 - 腮红扩散 */
#extensionsMenuButton:hover,
#quick-reply-rocket-button:hover {
  transform: scale(1.1);
  opacity: 1;
  animation: blushGlow 1.5s infinite alternate;
}

@keyframes blushGlow {
  0% {
    box-shadow: 0 0 5px rgba(255, 182, 193, 0.5);
    background-color: rgba(255, 182, 193, 0.15);
  }
  100% {
    box-shadow: 0 0 15px rgba(255, 182, 193, 0.8);
    background-color: rgba(255, 182, 193, 0.3);
  }
}

/* 点击效果 - 闪烁 */
#extensionsMenuButton:active,
#quick-reply-rocket-button:active {
  animation: blushBlink 0.3s;
}

@keyframes blushBlink {
  0% { opacity: 0.5; transform: scale(0.95); }
  50% { opacity: 1; transform: scale(1.1); }
  100% { opacity: 1; transform: scale(1); }
}

/* 隐藏所有原始图标 */
#options_button::before,
#extensionsMenuButton::before,
#send_but::before,
#quick-reply-rocket-button > i {
  display: none;
}

/* 底部图标自定义 */
/* 猫爪 */
#options_button,
#send_but { 
  background-image: url('https://files.catbox.moe/esvlpn.png'); 
}

#options_button:hover,
#send_but:hover { 
  background-image: url('https://files.catbox.moe/vy9mtp.png') !important; 
}

/* 腮红 */
#extensionsMenuButton { 
  background-image: url('https://files.catbox.moe/hdem26.png'); 
}
#quick-reply-rocket-button { 
  background-image: url('https://files.catbox.moe/2ezf76.png');
}

/* 输入框文字自定义 by墨千尾 */
#nonQRFormItems {
    position: relative;
}

#send_textarea::placeholder {
    color: transparent !important;
    text-shadow: none !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: "";
    position: absolute;
    left: 50%;
    top: 50%;
    width: 20px;
    height: 20px;
    background-image: url('https://files.catbox.moe/dk1zht.png');
    background-size: contain;
    background-repeat: no-repeat;
    transform: translate(-50%, -50%);
    pointer-events: none;
    z-index: 10;
    filter: brightness(0.3);
}

/* ----- 抽屉 ------ */
/* 全局头像 */
.avatar img,
body.big-avatar .avatar img{
  box-shadow: none;
  border: none;
}

/* 缩小锁定图标 */
#rm_button_characters,
#rm_button_panel_pin_div,
#lm_button_panel_pin_div,
#WI_button_panel_pin_div {
  font-size: calc(var(--mainFontSize) *1.2);
}

/* API标题特殊处理 */
#title_api {
  padding-bottom: 0; 
}

/* openai */
#openai_api-presets .title_restorable.standoutHeader
  .flex-container.gap3px div:not(label) {
  margin: 5px 0;
}

/* OpenAI范围块样式 */
#range_block_openai .range-block .toggle-description {
  margin-right: 0;
}

.range-block-title {
  text-align: left;
}

label[for="openai_image_inlining"] + div,
#openai_settings .inline-drawer-header .flex-container {
  gap: 0;
  text-align: left;
}

#openai_settings .inline-drawer-header .flex-container b {
  margin-right: 5px;
}

/* --- 标题栏 --- */
.standoutHeader,
.inline-drawer-header,
.inline-drawer-toggle.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#top-settings-holder h4:not(#ai-config-button):not(#rightNavHolder) {
  background: var(--theme-color-1);
  border-radius: var(--border-radius-small);
  padding-left: 7px;
  margin-bottom: 5px;
  box-shadow:
    0 1px 0 1px var(--theme-color-1);
  border: 1px solid var(--theme-color-3);
  outline: 1px solid var(--theme-color-2);
  transition: all 1s ease;
}

#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header {
  background: var(--theme-color-2);
}

/* 下拉箭头 */
.inline-drawer-icon {
  color: var(--theme-color-1);
  font-size: calc(var(--mainFontSize) *1.2);
  padding-right: 3px;
}

/* 取消拓展页悬停发光效果 */
.inline-drawer-toggle:hover, 
.inline-drawer-toggle:focus,
#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover, 
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover {
  filter: none !important;
  -webkit-filter: none !important;
}

/* 正则防误操作 */
#saved_regex_scripts, 
#saved_scoped_scripts {
  padding-right: 40px; 
}

.regex_script_name.flexGrow.overflow-hidden {
  white-space: normal;
}

.regex-script-label.flex-container {
  align-items: center;
}

/* 拓展页输入助手 */
.integrated-button-row {
  background: transparent !important;
  border-radius: var(--border-radius-small) !important;
  padding: 1px 7px!important;
}

.integrated-button-row .button-preview,
.integrated-button-row .shortcut-input,
.integrated-button-row .shortcut-clear-btn,
.integrated-button-row .custom-edit-btn,
.integrated-button-row .custom-edit-btn {
  -webkit-transform: scale(0.8);
  transform: scale(0.8);
}

/* --- 按钮 --- */
.menu_button:not(.mes_edit_buttons *) {
  background: var(--theme-color-1);
  border-radius: var(--border-radius-small);
  filter: none !important;
  box-shadow:
    inset 0 0 6px 6px var(--theme-color-2),
    inset 0 0 1px var(--theme-color-2),
    0 1px 0 1px var(--theme-color-3);
  outline: 1px solid var(--theme-color-2);
}

/* --- 下拉框 --- */
select {
  background-color: var(--theme-color-2);
  border: 1px solid var(--theme-color-1);
  outline: 1px solid var(--theme-color-2);
  box-shadow: 0 1px 0 1px var(--theme-color-3);
  border-radius: var(--border-radius-small);
  padding-left: 10px;
  filter: none !important;
  margin-bottom: 4px !important;
}

/* --- 复选框 --- */
input[type="checkbox"] {
  border-radius: 50%;
  border: 1px solid var(--theme-color-1);
  background: var(--theme-color-2);
  box-shadow: none;
  outline: 1px solid var(--theme-color-3);
}

.checkbox_label {
  display: flex;
  align-items: center;
}

/* 勾选框选中状态 */
input[type="checkbox"]:checked {
  background: var(--theme-color-1);
}

/* --- 输入框 --- */
input[type="text"],
input[type="number"]:not(.neo-range-input),
input[type="switch"],
input:not([type]),
textarea:not([type="search"]):not(#send_form textarea) {
  background: var(--theme-color-2);
  box-shadow:
    0 1px 0 1px var(--theme-color-1);
  border: 1px solid var(--theme-color-3);
  outline: 1px solid var(--theme-color-2);
  border-radius: var(--border-radius-small);
}

.neo-range-input {
  background: var(--theme-color-2);
  border-width: 1.5px;
  box-shadow:
    0 0.5px 0 0.5px var(--theme-color-3);
  border-radius: 0 0 var(--border-radius-small) var(--border-radius-small);
}

/* 输入状态 */
input[type="text"]:focus,
input[type="number"]:focus,
input[type="switch"]:focus,
input:not([type]):focus,
textarea:not([type="search"]):not(#send_form textarea):focus {
  background: color-mix(in srgb, var(--theme-color-2) 70%, white) !important;
}

/* 特殊输入框 */
.text_pole:not(.objective-task) {
  background-color: var(--theme-color-2);
  border-width: 1.2px;
  border-radius: var(--border-radius-small);
}

/* --- 弹窗 --- */
#character_popup, 
#dialogue_popup,
.draggable,        
#select_chat_popup, 
.popup:not(.transparent_dialogue_popup) {  
  border-radius: var(--border-radius-small);
  border-width: 1.5px;
}

/* 对话弹出窗文本 */
#dialogue_popup_text {
  padding-right: 10px; 
}

/* 给'提示词拆分'添加滚动条 */
.popup-content:has(#showRawPrompt) {
  overflow-y: auto;
  padding-right: 10px;
}

/* 通知提示框 */
div.toast.toast-error {
  border-radius: var(--border-radius-small) !important;
  border: 1.2px solid gray !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15) !important;
}

div.toast.toast-success {
  background-color: var(--theme-color-2) !important;
  border-radius: var(--border-radius-small) !important;
  color: var(--SmartThemeBodyColor) !important;
  border: 1.5px dashed var(--theme-color-1);
  outline: 1px solid var(--theme-color-2);
  box-shadow: 0 1px 0 2px var(--theme-color-3) !important;
}

/* --- 抽屉页背景 --- */
.drawer-content {
  background-image: url('https://files.catbox.moe/lhlwia.png');
  background-size: cover;
  background-repeat: no-repeat;
  background-position: center;
  border-radius: 0 0 var(--border-radius-small) var(--border-radius-small);
  border: none;
  border-bottom: 2.5px solid var(--theme-color-1);
  transition: all 0.5s ease;
}

/* 预设页和角色管理页 */
#left-nav-panel,
#right-nav-panel {
  top: 0; 
  height: 100dvh !important; 
  max-height: calc(100dvh - 1px);
}

@media screen and (max-width: 1000px) {
  #left-nav-panel,
  #right-nav-panel,
  .drawer-content {
  margin-top: 0; 
  }
}

#left-nav-panel,
#right-nav-panel {
  height: calc(100dvh - 45px) !important;
  max-height: calc(100dvh - var(--topBarBlockSize)) !important;
  }
}

/* --- 用户设置 & 格式化设置 --- */
#user-settings-block-content,
#AdvancedFormatting .flex-container.spaceEvenly {
  gap: 10px;
}

/* --- 预设页 --- */
/*提示词管理器 */
#completion_prompt_manager {
  width: 100%;
}

#completion_prompt_manager_list .completion_prompt_manager_list_separator {
  display: none !important;
}

/* 提示词 & 总词符数 */
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
  filter: none;
}

#completion_prompt_manager .completion_prompt_manager_header {
  color: var(--SmartThemeQuoteColor) !important;
  padding: 0;
}

.completion_prompt_manager_footer {
  padding: 0px !important;
}

#completion_prompt_manager .completion_prompt_manager_header_advanced span {
  margin-left: 0;
}

/* 去除阴影 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt
span
span
span {
  filter: none !important;
}

/* 未启用条目 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled {
  opacity: 0.65;
}

/* 未启用条目的字体颜色 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action, #completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid {
  color: var(--theme-color-1);
}

/* ----- 世界书 ----- */
#WorldInfo {
  margin-top: 0;
}
/* 世界书弹出窗口（iOS特定样式)  */
@supports (-webkit-touch-callout: none) {
  #world_popup {
    margin-top: 0;
    width: 100%;
  }
}

/* 世界书条目 */
.world_entry {
  margin-top: 5px;
  background: transparent;
}

/* 世界书条目卡片 */
.wi-card-entry {
  background: var(--theme-color-2);
  border-radius: var(--border-radius-small);
  border-width: 1.5px;
}

@media screen and (max-width: 1000px) {
  .world_entry_form .inline-drawer-header {
  border: none !important;
  outline: none;
  box-shadow: none;
  border-radius: var(--border-radius-small);
  background: var(--theme-color-2);
  }
}

/* 世界书选择器 */
.select2-container .select2-selection--multiple .select2-selection__choice,
.select2-container .select2-selection--single .select2-selection__choice {
  background: var(--theme-color-2);
}
span.select2.select2-container .select2-selection__choice__remove,
.select2_choice_clickable_buttonstyle
  +span.select2-container
  .select2-selection__choice__display {
  color: var(--SmartThemeBodyColor);
  line-height: 1.5;
  background-color: var(--theme-color-2);
  margin: 0px;
}
.select2-container
  .select2-selection--multiple
  .select2-selection__choice__remove {
  padding: 0 5px;
}

/* 单击展开 */
.inline-drawer-content {
    background: transparent !important;
    border-radius: 5px;
}

/* --- 图库 --- */
#form_bg_download .bg_example.add_bg_but.interactable{
  opacity: 0.5 !important;
  background-color: var(--theme-color-1);
}

.bg_example {
  box-shadow: none;
  border-width: 1.2px;
}

.bg_button{
  color: var(--theme-color-1);
  filter: none;
}

/* --- 用户管理器 --- */
.avatar-container {
  border: 2px dotted var(--theme-color-1);
}

.avatar-container.selected {
  background: var(--theme-color-2);
  border-color: var(--theme-color-3);
}

#movingUIPresets{
  margin-bottom: 0 !important;
}

/* --- 角色管理器 --- */
#CharListButtonAndHotSwaps {
  margin-bottom: calc(var(--mainFontSize) * 0.8);
}

label[for="char-management-dropdown"] {
  width: 100%;
}

#avatar_div {
  flex-direction: column;
}

#avatar_controls {
  align-items: center;
}

.character_select {
  margin-top: calc(var(--mainFontSize) * 0.8);
}

/* 星标角色卡 */
.character_select.is_fav .avatar {
  outline: 2px inset var(--SmartThemeQuoteColor);
}

.character_select.is_fav .ch_name {
  color: var(--SmartThemeQuoteColor);
}

.tag.excluded::after {
  font-size: calc(var(--mainFontSize) * 2);
}

.tag.actionable {
  font-size: var(--mainFontSize);
  min-height: calc(var(--mainFontSize) * 2);
  min-width: calc(var(--mainFontSize) * 2);
}

/* 角色收藏区滚动条 */
#HotSwapWrapper {
  overflow: hidden;
}

#HotSwapWrapper > div {
  overflow: auto hidden; 
  flex-wrap: nowrap;
  height: calc(var(--avatar-base-height) +  + 10px);
  max-height: calc(var(--avatar-base-height)* 2);
}

.avatars_inline {
  gap: 5px;
  flex-wrap: nowrap;
  overflow: visible;
}

/* ----- 🔸视觉小说模式🔸 ----- */
/* 使用前记得删除开头某串代码(已标) */
:root {
  --height: 40dvh; /* 🐑空白区域高度 */
}

body.waifuMode #sheld {
  background: transparent !important;
  margin: 0;
  padding: 0;
  top: var(--height);
  height: calc(100dvh - var(--height));
  min-height: none !important;
  -webkit-mask-image: 
    linear-gradient(to top, 
    rgba(0, 0, 0, 1) 0%, 
    rgba(0, 0, 0, 0.8) 80%, /* 顶部模糊程度(webkit浏览器修改此处) */
    rgba(0, 0, 0, 0) 100%);
  mask-image: 
    linear-gradient(to top, 
    rgba(0, 0, 0, 1) 0%, 
    rgba(0, 0, 0, 0.8) 80%, /* 🐑顶部模糊(修改括号内最后一个数字0-1,以及百分比) */
    rgba(0, 0, 0, 0) 100%);
}

